const DAY='(?:\\d{4}[-/.]\\d{1,2}[-/.]\\d{1,2}|\\d{1,2}[-/.]\\d{1,2}[-/.]\\d{2,4}|\\d{1,2}[- /]?[A-Za-z]{3}[- /]?(?:\\d{4}|\\d{2}))';
