const norm=s=>String(s??'').trim().toLowerCase().replace(/[._()]/g,' ').replace(/\s+/g,' ').trim();
export function parseMoney(s){s=String(s??'').trim();if(!s||/^[-—–]+$/.test(s))return null;let negative=/^\s*[-(]|\bDR\s*$/i.test(s);let v=Number(s.replace(/INR|Rs\.?|CR|DR|[₹,\s()+]/gi,'').replace(/^-/,''));return Number.isFinite(v)?(negative?-v:v):null}
const empty=s=>!String(s??'').trim()||/^[-–—]+$/.test(String(s).trim());
export function classifyBank(t){return{...t,salary:t.credit>0&&/\b(salary|payroll|sal\s*cr|salarycredit|salcredit)\b/i.test(t.description),bounce:/\b(bounc(?:e|ed)|dishonou?r(?:ed)?|insufficient (?:funds|bal)|(?:cheque|chq|ecs|nach|ach|si|mandate)[ /-]*(?:ret(?:urn)?|fail)|return charges|mandate fail)/i.test(t.description)}}
